CREATE DATABASE  IF NOT EXISTS`nacos_config`  DEFAULT CHARACTER SET utf8;

USE `nacos_config`;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `data_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `content` longtext CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT 'content',
  `md5` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `src_user` text CHARACTER SET utf8 COLLATE utf8_bin NULL COMMENT 'source user',
  `src_ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT 'source ip',
  `app_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `tenant_id` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT '' COMMENT '租户字段',
  `c_desc` varchar(256) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `c_use` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `effect` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `type` varchar(64) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL,
  `c_schema` text CHARACTER SET utf8 COLLATE utf8_bin NULL,
  `encrypted_data_key` text CHARACTER SET utf8 COLLATE utf8_bin NULL COMMENT '秘钥',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_configinfo_datagrouptenant`(`data_id`, `group_id`, `tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = 'config_info' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of config_info
-- ----------------------------
INSERT INTO `config_info` VALUES (1, 'common.yaml', 'DEFAULT_GROUP', 'mybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:mapper/*Mapper.xml\nfeign:\n  sentinel:\n    enabled: true\n  client:\n    config:\n      default:\n        readTimeout: 30000\n        connectTimeout: 10000\n\n\nminio:\n  endpointUrl: http://gmall-minio:9000\n  accessKey: admin\n  secreKey: admin123456\n  bucketName: gmall\n\n\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411\n    discovery-client-enabled: false\n    sender:\n      type: web\n  sleuth:\n    sampler:\n      rate: 100\n  cloud:\n    sentinel:\n      transport:\n        dashboard: http://gmall-sentinel:8858\n  rabbitmq:\n    host: gmall-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirm-type: correlated\n    publisher-returns: true\n    listener:\n      simple:\n        acknowledge-mode: manual #默认情况下消息消费者是自动确认消息的，如果要手动确认消息则需要修改确认模式为manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8', '517fb8ef5a0527d9cc93fb5a17e09f1f', '2024-11-12 09:16:33', '2026-06-16 14:08:55', 'nacos', '0:0:0:0:0:0:0:1', '', 'gmall', '', '', '', 'yaml', '', '');
INSERT INTO `config_info` VALUES (2, 'server-gateway-dev.yaml', 'DEFAULT_GROUP', 'server:\n  port: 80\nspring:\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n  cloud:\n    gateway:\n      globalcors:\n        cors-configurations:\n          \'[/**]\':\n            allowedOrigins: \"*\" #允许所有来源\n            allowedMethods: \"*\" #允许所有方式 GET POST DELETE ....\n            allowedHeaders: \"*\"\n            allowCredentials: true #跨域携带Cookie\n      discovery:      #是否与服务发现组件进行结合，通过 serviceId(必须设置成大写) 转发到具体的服务实例。默认为false，设为true便开启通过服务中心的自动根据 serviceId 创建路由的功能。\n        locator:      #路由访问方式：http://Gateway_HOST:Gateway_PORT/大写的serviceId/**，其中微服务应用名默认大写访问。\n          enabled: true\n      routes:\n        - id: service-product\n          uri: lb://service-product\n          predicates:\n            - Path=/*/product/** # 路径匹配\n        - id: service-item\n          uri: lb://service-item\n          predicates:\n            - Path=/*/item/**\n        - id: service-user\n          uri: lb://service-user\n          predicates:\n            - Path=/*/user/**\n        - id: service-cart\n          uri: lb://service-cart\n          predicates:\n            - Path=/*/cart/**\n        - id: service-order\n          uri: lb://service-order\n          predicates:\n            - Path=/*/order/**\n        - id: service-payment\n          uri: lb://service-payment\n          predicates:\n            - Path=/*/payment/**\n        - id: service-activity\n          uri: lb://service-activity\n          predicates:\n            - Path=/*/activity/** # 路径匹配\n        - id: service-comment\n          uri: lb://service-comment\n          predicates:\n            - Path=/*/comment/**\n        #==================web前端==========================\n        - id: web-item\n          uri: lb://web-all\n          predicates:\n            - Host=item.gmall.com\n        #==================首页前端==========================\n        - id: web-index\n          uri: lb://web-all\n          predicates:\n            - Host=www.gmall.com\n        - id: web-list\n          uri: lb://web-all\n          predicates:\n            - Host=list.gmall.com\n        - id: web-passport\n          uri: lb://web-all\n          predicates:\n            - Host=passport.gmall.com\n        - id: web-cart\n          uri: lb://web-all\n          predicates:\n            - Host=cart.gmall.com\n        - id: web-order\n          uri: lb://web-all\n          predicates:\n            - Host=order.gmall.com\n        - id: web-payment\n          uri: lb://web-all\n          predicates:\n            - Host=payment.gmall.com\n        - id: web-activity\n          uri: lb://web-all\n          predicates:\n            - Host=activity.gmall.com\n        - id: web-comment\n          uri: lb://web-all\n          predicates:\n            - Host=comment.gmall.com\nauthUrls:\n  url: trade.html,myOrder.html,#list.html,#addCart.html # 用户访问该控制器的时候，会被拦截跳转到登录！\n', 'b46fca1c152671fb8d79c29ba960a4cc', '2024-11-12 09:16:33', '2026-06-15 09:04:20', 'nacos', '0:0:0:0:0:0:0:1', '', 'gmall', '', '', '', 'yaml', '', '');
