INSERT INTO `config_info` VALUES (25, 'service-ware-dev.yaml', 'DEFAULT_GROUP', 'server:\n  port: 9001\n\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:com/atguigu/gmall/*/mapper/*.xml\n\nspring:\n  thymeleaf:\n    #模板的模式，支持 HTML, XML TEXT JAVASCRIPT\n    mode: HTML5\n    #编码 可不用配置\n    encoding: UTF-8\n    #开发配置为false,避免修改模板还要重启服务器\n    cache: false\n    #配置模板路径，默认是templates，可以不用配置\n    prefix: classpath:/templates/\n  rabbitmq:\n    host: gmall-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirms: true\n    publisher-returns: true\n    listener:\n      simple:\n        cknowledge-mode: manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.jdbc.Driver\n    url: jdbc:mysql://gmall-mysql:33057/gmall_ware?characterEncoding=utf-8&useSSL=false\n    username: root\n    password: 123456\n    hikari:\n      connection-test-query: SELECT 1\n      connection-timeout: 60000\n      idle-timeout: 500000\n      max-lifetime: 540000\n      maximum-pool-size: 12\n      minimum-idle: 10\n      pool-name: GuliHikariPool\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n\norder:\n  split:\n    url: http://localhost:8204/api/order/orderSplit', 'bb755d52681e244306c39c65fe58a1d9', '2024-11-12 09:23:17', '2026-06-15 08:09:05', 'nacos', '0:0:0:0:0:0:0:1', '', 'gmall', '', '', '', 'yaml', '', '');
