INSERT INTO `config_info` VALUES (37, 'service-comment-local.yaml', 'DEFAULT_GROUP', 'server:\n  port: 8211\nspring:\n  main:\n    allow-bean-definition-overriding: true #当遇到同样名字的时候，是否允许覆盖注册\n  data:\n    mongodb:\n      host: gmall-mongdb\n      port: 27017\n      database: gmall #指定操作的数据库\n  # redis:\n  #   host: 192.168.200.129\n  #   port: 6379\n  #   database: 0\n  #   timeout: 1800000\n  #   password:\n  #   lettuce:\n  #     pool:\n  #       max-active: 20 #最大连接数\n  #       max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n  #       max-idle: 5    #最大空闲\n  #       min-idle: 0     #最小空闲\n  # jackson:\n  #   date-format: yyyy-MM-dd HH:mm:ss\n  #   time-zone: GMT+8', '58c16172c83bb021113169c93fb318e9', '2026-01-30 04:08:12', '2026-01-30 04:08:12', NULL, '192.168.200.1', '', 'gmall', NULL, NULL, NULL, 'yaml', NULL, NULL);
