INSERT INTO `his_config_info` VALUES (39, 99, 'service-ware-local.yaml', 'DEFAULT_GROUP', '', 'server:\n  port: 9001\n\nmybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:com/atguigu/gmall/*/mapper/*.xml\n\nspring:\n  thymeleaf:\n    #模板的模式，支持 HTML, XML TEXT JAVASCRIPT\n    mode: HTML5\n    #编码 可不用配置\n    encoding: UTF-8\n    #开发配置为false,避免修改模板还要重启服务器\n    cache: false\n    #配置模板路径，默认是templates，可以不用配置\n    prefix: classpath:/templates/\n  rabbitmq:\n    host: gmall-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirms: true\n    publisher-returns: true\n    listener:\n      simple:\n        cknowledge-mode: manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: gmall-redis\n    port: gmall-redis-port\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  datasource:\n    type: com.zaxxer.hikari.HikariDataSource\n    driver-class-name: com.mysql.jdbc.Driver\n    url: jdbc:mysql://gmall-mysql:gmall-mysql-port/gmall_ware?characterEncoding=utf-8&useSSL=false\n    username: root\n    password: 123456\n    hikari:\n      connection-test-query: SELECT 1\n      connection-timeout: 60000\n      idle-timeout: 500000\n      max-lifetime: 540000\n      maximum-pool-size: 12\n      minimum-idle: 10\n      pool-name: GuliHikariPool\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8\n\norder:\n  split:\n    url: http://localhost:8204/api/order/orderSplit', '7662e117f8713ac531aca34516e72058', '2026-06-15 16:06:43', '2026-06-15 08:06:44', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (2, 100, 'server-gateway-dev.yaml', 'DEFAULT_GROUP', '', 'server:\n  port: 80\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411/\n    sender:\n      type: web\n  sleuth:\n    sampler:\n      rate: 100\n  redis:\n    host: gmall-redis\n    port: gmall-redis-port\n    database: 0\n    timeout: 1800000\n    password: 123456\n  cloud:\n    gateway:\n      globalcors:\n        cors-configurations:\n          \'[/**]\':\n            allowedOrigins: \"*\" #允许所有来源\n            allowedMethods: \"*\" #允许所有方式 GET POST DELETE ....\n            allowedHeaders: \"*\"\n            allowCredentials: true #跨域携带Cookie\n      discovery:      #是否与服务发现组件进行结合，通过 serviceId(必须设置成大写) 转发到具体的服务实例。默认为false，设为true便开启通过服务中心的自动根据 serviceId 创建路由的功能。\n        locator:      #路由访问方式：http://Gateway_HOST:Gateway_PORT/大写的serviceId/**，其中微服务应用名默认大写访问。\n          enabled: true\n      routes:\n        - id: service-product\n          uri: lb://service-product\n          predicates:\n            - Path=/*/product/** # 路径匹配\n        - id: service-item\n          uri: lb://service-item\n          predicates:\n            - Path=/*/item/**\n        - id: service-user\n          uri: lb://service-user\n          predicates:\n            - Path=/*/user/**\n        - id: service-cart\n          uri: lb://service-cart\n          predicates:\n            - Path=/*/cart/**\n        - id: service-order\n          uri: lb://service-order\n          predicates:\n            - Path=/*/order/**\n        - id: service-payment\n          uri: lb://service-payment\n          predicates:\n            - Path=/*/payment/**\n        - id: service-activity\n          uri: lb://service-activity\n          predicates:\n            - Path=/*/activity/** # 路径匹配\n        - id: service-comment\n          uri: lb://service-comment\n          predicates:\n            - Path=/*/comment/**\n        #==================web前端==========================\n        - id: web-item\n          uri: lb://web-all\n          predicates:\n            - Host=item.gmall.com\n        #==================首页前端==========================\n        - id: web-index\n          uri: lb://web-all\n          predicates:\n            - Host=www.gmall.com\n        - id: web-list\n          uri: lb://web-all\n          predicates:\n            - Host=list.gmall.com\n        - id: web-passport\n          uri: lb://web-all\n          predicates:\n            - Host=passport.gmall.com\n        - id: web-cart\n          uri: lb://web-all\n          predicates:\n            - Host=cart.gmall.com\n        - id: web-order\n          uri: lb://web-all\n          predicates:\n            - Host=order.gmall.com\n        - id: web-payment\n          uri: lb://web-all\n          predicates:\n            - Host=payment.gmall.com\n        - id: web-activity\n          uri: lb://web-all\n          predicates:\n            - Host=activity.gmall.com\n        - id: web-comment\n          uri: lb://web-all\n          predicates:\n            - Host=comment.gmall.com\nauthUrls:\n  url: trade.html,myOrder.html,#list.html,#addCart.html # 用户访问该控制器的时候，会被拦截跳转到登录！\n', 'b8228bf3056ab50d95e0e824f9128c4d', '2026-06-15 16:06:59', '2026-06-15 08:06:59', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
