INSERT INTO `his_config_info` VALUES (1, 108, 'common.yaml', 'DEFAULT_GROUP', '', 'mybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:mapper/*Mapper.xml\nfeign:\n  sentinel:\n    enabled: true\n  client:\n    config:\n      default:\n        readTimeout: 30000\n        connectTimeout: 10000\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411\n    discovery-client-enabled: false\n    sender:\n      type: web\n  cloud:\n    sentinel:\n      transport:\n        dashboard: http://gmall-sentinel:8858\n  rabbitmq:\n    host: gmall-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirm-type: correlated\n    publisher-returns: true\n    listener:\n      simple:\n        acknowledge-mode: manual #默认情况下消息消费者是自动确认消息的，如果要手动确认消息则需要修改确认模式为manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8', '1b80599669125e03ce9342944e74b3d7', '2026-06-15 17:03:44', '2026-06-15 09:03:45', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (26, 109, 'server-gateway-local.yaml', 'DEFAULT_GROUP', '', 'server:\n  port: 80\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411/\n    sender:\n      type: web\n  sleuth:\n    sampler:\n      rate: 100\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n  cloud:\n    gateway:\n      globalcors:\n        cors-configurations:\n          \'[/**]\':\n            allowedOrigins: \"*\" #允许所有来源\n            allowedMethods: \"*\" #允许所有方式 GET POST DELETE ....\n            allowedHeaders: \"*\"\n            allowCredentials: true #跨域携带Cookie\n      discovery:      #是否与服务发现组件进行结合，通过 serviceId(必须设置成大写) 转发到具体的服务实例。默认为false，设为true便开启通过服务中心的自动根据 serviceId 创建路由的功能。\n        locator:      #路由访问方式：http://Gateway_HOST:Gateway_PORT/大写的serviceId/**，其中微服务应用名默认大写访问。\n          enabled: true\n      routes:\n        - id: service-product\n          uri: lb://service-product\n          predicates:\n            - Path=/*/product/** # 路径匹配\n        - id: service-item\n          uri: lb://service-item\n          predicates:\n            - Path=/*/item/**\n        - id: service-user\n          uri: lb://service-user\n          predicates:\n            - Path=/*/user/**\n        - id: service-cart\n          uri: lb://service-cart\n          predicates:\n            - Path=/*/cart/**\n        - id: service-order\n          uri: lb://service-order\n          predicates:\n            - Path=/*/order/**\n        - id: service-payment\n          uri: lb://service-payment\n          predicates:\n            - Path=/*/payment/**\n        - id: service-activity\n          uri: lb://service-activity\n          predicates:\n            - Path=/*/activity/** # 路径匹配\n        - id: service-comment\n          uri: lb://service-comment\n          predicates:\n            - Path=/*/comment/**\n        #==================web前端==========================\n        - id: web-item\n          uri: lb://web-all\n          predicates:\n            - Host=item.gmall.com\n        #==================首页前端==========================\n        - id: web-index\n          uri: lb://web-all\n          predicates:\n            - Host=www.gmall.com\n        - id: web-list\n          uri: lb://web-all\n          predicates:\n            - Host=list.gmall.com\n        - id: web-passport\n          uri: lb://web-all\n          predicates:\n            - Host=passport.gmall.com\n        - id: web-cart\n          uri: lb://web-all\n          predicates:\n            - Host=cart.gmall.com\n        - id: web-order\n          uri: lb://web-all\n          predicates:\n            - Host=order.gmall.com\n        - id: web-payment\n          uri: lb://web-all\n          predicates:\n            - Host=payment.gmall.com\n        - id: web-activity\n          uri: lb://web-all\n          predicates:\n            - Host=activity.gmall.com\n        - id: web-comment\n          uri: lb://web-all\n          predicates:\n            - Host=comment.gmall.com\nauthUrls:\n  url: trade.html,myOrder.html,#list.html,#addCart.html # 用户访问该控制器的时候，会被拦截跳转到登录！\n', 'ed40f5692afd4cfd792825ea3fe1871f', '2026-06-15 17:03:59', '2026-06-15 09:03:59', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (2, 110, 'server-gateway-dev.yaml', 'DEFAULT_GROUP', '', 'server:\n  port: 80\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411/\n    sender:\n      type: web\n  sleuth:\n    sampler:\n      rate: 100\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n  cloud:\n    gateway:\n      globalcors:\n        cors-configurations:\n          \'[/**]\':\n            allowedOrigins: \"*\" #允许所有来源\n            allowedMethods: \"*\" #允许所有方式 GET POST DELETE ....\n            allowedHeaders: \"*\"\n            allowCredentials: true #跨域携带Cookie\n      discovery:      #是否与服务发现组件进行结合，通过 serviceId(必须设置成大写) 转发到具体的服务实例。默认为false，设为true便开启通过服务中心的自动根据 serviceId 创建路由的功能。\n        locator:      #路由访问方式：http://Gateway_HOST:Gateway_PORT/大写的serviceId/**，其中微服务应用名默认大写访问。\n          enabled: true\n      routes:\n        - id: service-product\n          uri: lb://service-product\n          predicates:\n            - Path=/*/product/** # 路径匹配\n        - id: service-item\n          uri: lb://service-item\n          predicates:\n            - Path=/*/item/**\n        - id: service-user\n          uri: lb://service-user\n          predicates:\n            - Path=/*/user/**\n        - id: service-cart\n          uri: lb://service-cart\n          predicates:\n            - Path=/*/cart/**\n        - id: service-order\n          uri: lb://service-order\n          predicates:\n            - Path=/*/order/**\n        - id: service-payment\n          uri: lb://service-payment\n          predicates:\n            - Path=/*/payment/**\n        - id: service-activity\n          uri: lb://service-activity\n          predicates:\n            - Path=/*/activity/** # 路径匹配\n        - id: service-comment\n          uri: lb://service-comment\n          predicates:\n            - Path=/*/comment/**\n        #==================web前端==========================\n        - id: web-item\n          uri: lb://web-all\n          predicates:\n            - Host=item.gmall.com\n        #==================首页前端==========================\n        - id: web-index\n          uri: lb://web-all\n          predicates:\n            - Host=www.gmall.com\n        - id: web-list\n          uri: lb://web-all\n          predicates:\n            - Host=list.gmall.com\n        - id: web-passport\n          uri: lb://web-all\n          predicates:\n            - Host=passport.gmall.com\n        - id: web-cart\n          uri: lb://web-all\n          predicates:\n            - Host=cart.gmall.com\n        - id: web-order\n          uri: lb://web-all\n          predicates:\n            - Host=order.gmall.com\n        - id: web-payment\n          uri: lb://web-all\n          predicates:\n            - Host=payment.gmall.com\n        - id: web-activity\n          uri: lb://web-all\n          predicates:\n            - Host=activity.gmall.com\n        - id: web-comment\n          uri: lb://web-all\n          predicates:\n            - Host=comment.gmall.com\nauthUrls:\n  url: trade.html,myOrder.html,#list.html,#addCart.html # 用户访问该控制器的时候，会被拦截跳转到登录！\n', 'ed40f5692afd4cfd792825ea3fe1871f', '2026-06-15 17:04:20', '2026-06-15 09:04:20', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (40, 111, 'common.yaml', 'DEFAULT_GROUP', '', 'mybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:mapper/*Mapper.xml\nfeign:\n  sentinel:\n    enabled: true\n  client:\n    config:\n      default:\n        readTimeout: 30000\n        connectTimeout: 10000\nspring:\n  zipkin:\n    base-url: http://openhis-zipkin:9411\n    discovery-client-enabled: false\n    sender:\n      type: web\n  cloud:\n    sentinel:\n      transport:\n        dashboard: http://openhis-sentinel:8858\n  rabbitmq:\n    host: openhis-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirm-type: correlated\n    publisher-returns: true\n    listener:\n      simple:\n        acknowledge-mode: manual #默认情况下消息消费者是自动确认消息的，如果要手动确认消息则需要修改确认模式为manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: openhis-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8', '3e6e5d79aa77ffd450a8b843fcd59f1a', '2026-06-16 20:44:57', '2026-06-16 12:44:57', 'nacos', '127.0.0.1', 'U', 'openhis', '');
INSERT INTO `his_config_info` VALUES (29, 112, 'service-item-local.yaml', 'DEFAULT_GROUP', '', 'server:\r\n  port: 8202', 'bb8505f90d2099a1d5267b0e037cf1a3', '2026-06-16 21:50:05', '2026-06-16 13:50:06', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (1, 113, 'common.yaml', 'DEFAULT_GROUP', '', 'mybatis-plus:\n  configuration:\n    log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  mapper-locations: classpath:mapper/*Mapper.xml\nfeign:\n  sentinel:\n    enabled: true\n  client:\n    config:\n      default:\n        readTimeout: 30000\n        connectTimeout: 10000\nspring:\n  zipkin:\n    base-url: http://gmall-zipkin:9411\n    discovery-client-enabled: false\n    sender:\n      type: web\n  sleuth:\n    sampler:\n      rate: 100\n  cloud:\n    sentinel:\n      transport:\n        dashboard: http://gmall-sentinel:8858\n  rabbitmq:\n    host: gmall-rabbitmq\n    port: 5672\n    username: admin\n    password: admin\n    publisher-confirm-type: correlated\n    publisher-returns: true\n    listener:\n      simple:\n        acknowledge-mode: manual #默认情况下消息消费者是自动确认消息的，如果要手动确认消息则需要修改确认模式为manual\n        prefetch: 1 # 消费者每次从队列获取的消息数量。此属性当不设置时为：轮询分发，设置为1为：公平分发\n  redis:\n    host: gmall-redis\n    port: 6379\n    database: 0\n    timeout: 1800000\n    password: 123456\n    lettuce:\n      pool:\n        max-active: 20 #最大连接数\n        max-wait: -1    #最大阻塞等待时间(负数表示没限制)\n        max-idle: 5    #最大空闲\n        min-idle: 0     #最小空闲\n  jackson:\n    date-format: yyyy-MM-dd HH:mm:ss\n    time-zone: GMT+8', 'b619e6878e836b24003ebfd8b5f87562', '2026-06-16 22:08:54', '2026-06-16 14:08:55', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (36, 114, 'web-all-local.yaml', 'DEFAULT_GROUP', '', 'server:\r\n  port: 8300\r\n\r\nspring:\r\n  thymeleaf:\r\n    mode: LEGACYHTML5\r\n    #编码 可不用配置\r\n    encoding: UTF-8\r\n    #开发配置为false,避免修改模板还要重启服务器\r\n    cache: false\r\n    #配置模板路径，默认是templates，可以不用配置\r\n    prefix: classpath:/templates/\r\n', '63683bfbfac5775737692b3850b78962', '2026-06-16 22:26:33', '2026-06-16 14:26:33', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');
INSERT INTO `his_config_info` VALUES (12, 115, 'web-all-dev.yaml', 'DEFAULT_GROUP', '', 'server:\r\n  port: 8300\r\n\r\nspring:\r\n  thymeleaf:\r\n    mode: LEGACYHTML5\r\n    #编码 可不用配置\r\n    encoding: UTF-8\r\n    #开发配置为false,避免修改模板还要重启服务器\r\n    cache: false\r\n    #配置模板路径，默认是templates，可以不用配置\r\n    prefix: classpath:/templates/\r\n', '63683bfbfac5775737692b3850b78962', '2026-06-16 22:27:35', '2026-06-16 14:27:36', 'nacos', '0:0:0:0:0:0:0:1', 'U', 'gmall', '');

-- ----------------------------
-- Table structure for permissions
-- ----------------------------
DROP TABLE IF EXISTS `permissions`;
CREATE TABLE `permissions`  (
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `resource` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `action` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  UNIQUE INDEX `uk_role_permission`(`role`, `resource`, `action`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of permissions
-- ----------------------------

-- ----------------------------
-- Table structure for roles
-- ----------------------------
DROP TABLE IF EXISTS `roles`;
CREATE TABLE `roles`  (
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  UNIQUE INDEX `idx_user_role`(`username`, `role`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of roles
-- ----------------------------
INSERT INTO `roles` VALUES ('nacos', 'ROLE_ADMIN');

-- ----------------------------
-- Table structure for tenant_capacity
-- ----------------------------
DROP TABLE IF EXISTS `tenant_capacity`;
CREATE TABLE `tenant_capacity`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL DEFAULT '' COMMENT 'Tenant ID',
  `quota` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '配额，0表示使用默认值',
  `usage` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '使用量',
  `max_size` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '单个配置大小上限，单位为字节，0表示使用默认值',
  `max_aggr_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '聚合子配置最大个数',
  `max_aggr_size` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '单个聚合数据的子配置大小上限，单位为字节，0表示使用默认值',
  `max_history_count` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '最大变更历史数量',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = '租户容量信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tenant_capacity
-- ----------------------------

-- ----------------------------
-- Table structure for tenant_info
-- ----------------------------
DROP TABLE IF EXISTS `tenant_info`;
CREATE TABLE `tenant_info`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'id',
  `kp` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL COMMENT 'kp',
  `tenant_id` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT '' COMMENT 'tenant_id',
  `tenant_name` varchar(128) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT '' COMMENT 'tenant_name',
  `tenant_desc` varchar(256) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT 'tenant_desc',
  `create_source` varchar(32) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT 'create_source',
  `gmt_create` bigint(20) NOT NULL COMMENT '创建时间',
  `gmt_modified` bigint(20) NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_info_kptenantid`(`kp`, `tenant_id`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8 COLLATE = utf8_bin COMMENT = 'tenant_info' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of tenant_info
-- ----------------------------
INSERT INTO `tenant_info` VALUES (1, '1', 'gmall', 'gmall', 'gmall', 'nacos', 1731402972662, 1731402972662);
